import { RendererCanvas } from '../../../lib';

interface AreaInput {
	name: string;
	width: number;
	length: number;
	color: number;
	isFixed?: boolean;
	relatedTo?: 'reception' | 'loading';
}

interface Point {
	x: number;
	y: number;
}

interface Rect {
	x: number;
	y: number;
	width: number;
	height: number;
}

interface PlacedArea extends Rect {
	name: string;
	color: string;
	isFixed?: boolean;
}

type EdgePosition = 'top' | 'right' | 'bottom' | 'left';

class TreemapLayout {
	private areas: PlacedArea[] = [];

	constructor(
		private totalWidth: number,
		private totalHeight: number,
		private inputData: AreaInput[],
		private receptionPos: Point,
		private loadingPos: Point,
	) {}

	public calculate(): PlacedArea[] {
		this.areas = [];

		const receptionEdge = this.getEdgeFromPoint(this.receptionPos);
		const loadingEdge = this.getEdgeFromPoint(this.loadingPos);

		const fixedAreas: PlacedArea[] = [];
		const flexibleData: AreaInput[] = [];

		const receptionArea = this.inputData.find((a) => a.name === 'Reception');
		if (receptionArea) {
			fixedAreas.push(this.placeAreaAtEdge(receptionArea, receptionEdge));
		}

		const loadingArea = this.inputData.find((a) => a.name === 'Loading Zone');
		if (loadingArea) {
			fixedAreas.push(this.placeAreaAtEdge(loadingArea, loadingEdge));
		}

		this.inputData.forEach((area) => {
			if (area.name !== 'Reception' && area.name !== 'Loading Zone') {
				flexibleData.push(area);
			}
		});
		const availableRect = this.getAvailableRect(fixedAreas, receptionEdge, loadingEdge);

		if (flexibleData.length > 0) {
			const totalInputArea = flexibleData.reduce((sum, a) => sum + a.width * a.length, 0);
			const data = flexibleData
				.map((a) => ({
					name: a.name,
					color: `#${a.color.toString(16).padStart(6, '0')}`,
					value: a.width * a.length,
					relatedTo: a.relatedTo,
				}))
				.sort((a, b) => b.value - a.value);

			const canvasArea = availableRect.width * availableRect.height;
			const scale = canvasArea / totalInputArea;
			const values = data.map((d) => d.value * scale);

			this.squarify(availableRect.x, availableRect.y, availableRect.width, availableRect.height, values, data);
		}

		return [...fixedAreas, ...this.areas];
	}

	private getEdgeFromPoint(point: Point): EdgePosition {
		const distToTop = point.y;
		const distToBottom = this.totalHeight - point.y;
		const distToLeft = point.x;
		const distToRight = this.totalWidth - point.x;

		const min = Math.min(distToTop, distToBottom, distToLeft, distToRight);

		if (min === distToTop) return 'top';
		if (min === distToBottom) return 'bottom';
		if (min === distToLeft) return 'left';
		return 'right';
	}

	private placeAreaAtEdge(area: AreaInput, edge: EdgePosition): PlacedArea {
		const color = `#${area.color.toString(16).padStart(6, '0')}`;
		const targetArea = area.width * area.length;

		let x = 0,
			y = 0,
			width = 0,
			height = 0;

		switch (edge) {
			case 'top':
				height = Math.sqrt(targetArea * (this.totalHeight / this.totalWidth));
				width = this.totalWidth;
				x = 0;
				y = 0;
				break;
			case 'bottom':
				height = Math.sqrt(targetArea * (this.totalHeight / this.totalWidth));
				width = this.totalWidth;
				x = 0;
				y = this.totalHeight - height;
				break;
			case 'left':
				width = Math.sqrt(targetArea * (this.totalWidth / this.totalHeight));
				height = this.totalHeight;
				x = 0;
				y = 0;
				break;
			case 'right':
				width = Math.sqrt(targetArea * (this.totalWidth / this.totalHeight));
				height = this.totalHeight;
				x = this.totalWidth - width;
				y = 0;
				break;
		}

		return { x, y, width, height, name: area.name, color, isFixed: true };
	}

	private getAvailableRect(fixedAreas: PlacedArea[], receptionEdge: EdgePosition, loadingEdge: EdgePosition): Rect {
		let x = 0,
			y = 0,
			width = this.totalWidth,
			height = this.totalHeight;

		fixedAreas.forEach((area) => {
			if (area.name === 'Reception') {
				switch (receptionEdge) {
					case 'top':
						y += area.height;
						height -= area.height;
						break;
					case 'bottom':
						height -= area.height;
						break;
					case 'left':
						x += area.width;
						width -= area.width;
						break;
					case 'right':
						width -= area.width;
						break;
				}
			}
			if (area.name === 'Loading Zone') {
				switch (loadingEdge) {
					case 'top':
						y += area.height;
						height -= area.height;
						break;
					case 'bottom':
						height -= area.height;
						break;
					case 'left':
						x += area.width;
						width -= area.width;
						break;
					case 'right':
						width -= area.width;
						break;
				}
			}
		});

		return { x, y, width, height };
	}

	private squarify(x: number, y: number, w: number, h: number, values: number[], originalData: any[]) {
		if (values.length === 0) return;

		const isHorizontal = w >= h;
		const side = isHorizontal ? h : w;

		let sum = 0;
		let lastWorst = Infinity;
		let count = 0;

		for (let i = 0; i < values.length; i++) {
			const nextSum = sum + values[i];
			const currentWorst = this.getWorstAspectRatio(values.slice(0, i + 1), side, nextSum);

			if (currentWorst > lastWorst) break;

			sum = nextSum;
			lastWorst = currentWorst;
			count++;
		}

		const groupValues = values.slice(0, count);
		const groupData = originalData.slice(0, count);
		const thickness = sum / side;

		let offset = 0;
		for (let i = 0; i < groupValues.length; i++) {
			const areaSize = groupValues[i];
			const length = areaSize / thickness;

			if (isHorizontal) {
				this.areas.push({ x, y: y + offset, width: thickness, height: length, ...groupData[i] });
			} else {
				this.areas.push({ x: x + offset, y, width: length, height: thickness, ...groupData[i] });
			}
			offset += length;
		}

		if (isHorizontal) {
			this.squarify(x + thickness, y, w - thickness, h, values.slice(count), originalData.slice(count));
		} else {
			this.squarify(x, y + thickness, w, h - thickness, values.slice(count), originalData.slice(count));
		}
	}

	private getWorstAspectRatio(row: number[], side: number, sum: number): number {
		const max = Math.max(...row);
		const min = Math.min(...row);
		return Math.max((side ** 2 * max) / sum ** 2, sum ** 2 / (side ** 2 * min));
	}
}

export class Solution {
	public divHost: HTMLElement;
	public renderer: Renderer;
	constructor(id: string) {
		this.divHost = document.getElementById(id);

		this.divHost.style.display = 'flex';
		this.divHost.style.flexDirection = 'column';
		this.divHost.style.alignItems = 'center';
		this.divHost.style.gap = '15px';
		this.divHost.style.padding = '15px';

		const controlPanel = document.createElement('div');
		controlPanel.style.width = '100%';
		controlPanel.style.maxWidth = '800px';

		const canvasContainer = document.createElement('div');
		canvasContainer.id = 'canvas-container';
		canvasContainer.style.backgroundColor = '#555';

		this.divHost.appendChild(controlPanel);
		this.divHost.appendChild(canvasContainer);

		this.renderer = new Renderer(canvasContainer, controlPanel);
	}
	public destroy() {
		if (this.divHost) {
			try {
				while (this.divHost.firstChild) {
					this.divHost.removeChild(this.divHost.firstChild);
				}
			} catch (error) {
				console.error('Error in destroy method:', error);
			}
		}
	}
}

export class Renderer extends RendererCanvas {
	private placedAreas: PlacedArea[] = [];
	private areasData: AreaInput[];
	private controlPanel: HTMLElement;

	private totalCanvasWidth: number = 800;
	private totalCanvasHeight: number = 500;
	private receptionPoint: Point | null = null;
	private loadingPoint: Point | null = null;
	private clickMode: 'reception' | 'loading' | null = 'reception';

	constructor(canvasContainer: HTMLElement, controlPanel: HTMLElement) {
		super(canvasContainer);
		this.controlPanel = controlPanel;
		this.canvas.style.cursor = 'crosshair';

		this.areasData = [
			{ color: 0x4477aa, width: 212.5, length: 120, name: 'Integration Bay', relatedTo: 'loading' },
			{ color: 0x333333, width: 85, length: 120, name: 'Loading Zone', isFixed: true },
			{ color: 0xe1857f, width: 84, length: 70, name: 'Fabrication', relatedTo: 'loading' },
			{ color: 0xe9cb70, width: 84, length: 70, name: 'Finishing Zone', relatedTo: 'loading' },
			{ color: 0xed9e66, width: 84, length: 70, name: 'Hardware', relatedTo: 'loading' },
			{ color: 0x8c7bf0, width: 84, length: 60, name: 'Network Lab', relatedTo: 'loading' },
			{ color: 0x44aa77, width: 212.5, length: 45, name: 'Work Desk Zone', relatedTo: 'reception' },
			{ color: 0xb19ff3, width: 85, length: 70, name: 'Demo Area', relatedTo: 'reception' },
			{ color: 0xaa44aa, width: 85, length: 80, name: 'Reception', isFixed: true },
			{ color: 0xaa6644, width: 110, length: 100, name: 'Rest room', relatedTo: 'reception' },
			{ color: 0xc1d878, width: 90, length: 50, name: 'Ping Pong', relatedTo: 'reception' },
			{ color: 0xc1d878, width: 90, length: 50, name: 'Wellness', relatedTo: 'reception' },
		];

		this.createControls();
		this.updateCanvasSize();
		this.setupCanvasClick();
		this.start();
	}

	private setupCanvasClick() {
		this.canvas.addEventListener('click', (e) => {
			const rect = this.canvas.getBoundingClientRect();
			const x = e.clientX - rect.left;
			const y = e.clientY - rect.top;

			if (this.clickMode === 'reception') {
				this.receptionPoint = { x, y };
				this.clickMode = 'loading';
				// this.updateStatusText();
			} else if (this.clickMode === 'loading') {
				this.loadingPoint = { x, y };
				this.clickMode = null;
				this.canvas.style.cursor = 'default';
				// this.updateStatusText();
				this.updateLayout();
			}

			this.isStatic = false;
		});
	}
	private createControls() {
		this.controlPanel.innerHTML = `
			<div style="background: #333; padding: 15px; border-radius: 8px; color: white;">
				<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px;">
					<h3 style="margin: 0;">Spatial Partitioning</h3>
					<button id="reset-btn" style="padding: 8px 16px; background: #333; border: none; border-radius: 4px; color: white; cursor: pointer; font-weight: bold;">reset</button>
				</div>
				
				<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 15px; margin-bottom: 15px;">
					<div>
						<label style="display: block; margin-bottom: 8px; font-size: 14px;">
							Width: <span id="canvas-width-val">${this.totalCanvasWidth}</span>px
							<input type="range" id="canvas-width" min="600" max="1200" value="${this.totalCanvasWidth}" step="50" style="width: 100%; margin-top: 4px;">
						</label>
					</div>
					<div>
						<label style="display: block; margin-bottom: 8px; font-size: 14px;">
							Length: <span id="canvas-height-val">${this.totalCanvasHeight}</span>px
							<input type="range" id="canvas-height" min="400" max="800" value="${this.totalCanvasHeight}" step="50" style="width: 100%; margin-top: 4px;">
						</label>
					</div>
				</div>
				
				<details style="margin-top: 10px;">
					<summary style="cursor: pointer; padding: 8px; background: #444; border-radius: 4px; user-select: none;">Controller</summary>
					<div id="area-controls" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 10px; margin-top: 10px; max-height: 300px; overflow-y: auto; padding: 5px;">
					</div>
				</details>
			</div>
		`;

		// Reset button
		const resetBtn = this.controlPanel.querySelector('#reset-btn') as HTMLButtonElement;
		resetBtn.addEventListener('click', () => {
			this.receptionPoint = null;
			this.loadingPoint = null;
			this.clickMode = 'reception';
			this.canvas.style.cursor = 'crosshair';
			this.placedAreas = [];
			// this.updateStatusText();
			this.isStatic = false;
		});

		// Canvas size controls
		const widthInput = this.controlPanel.querySelector('#canvas-width') as HTMLInputElement;
		const heightInput = this.controlPanel.querySelector('#canvas-height') as HTMLInputElement;
		const widthVal = this.controlPanel.querySelector('#canvas-width-val') as HTMLElement;
		const heightVal = this.controlPanel.querySelector('#canvas-height-val') as HTMLElement;

		widthInput.addEventListener('input', () => {
			this.totalCanvasWidth = parseInt(widthInput.value);
			widthVal.textContent = widthInput.value;
			this.updateCanvasSize();
			if (this.receptionPoint && this.loadingPoint) this.updateLayout();
		});

		heightInput.addEventListener('input', () => {
			this.totalCanvasHeight = parseInt(heightInput.value);
			heightVal.textContent = heightInput.value;
			this.updateCanvasSize();
			if (this.receptionPoint && this.loadingPoint) this.updateLayout();
		});

		// Area controls
		const container = this.controlPanel.querySelector('#area-controls') as HTMLElement;

		this.areasData.forEach((area, index) => {
			if (area.isFixed) return; // Skip fixed areas

			const areaControl = document.createElement('div');
			areaControl.style.backgroundColor = '#444';
			areaControl.style.padding = '10px';
			areaControl.style.borderRadius = '4px';
			areaControl.style.borderLeft = `3px solid #${area.color.toString(16).padStart(6, '0')}`;
			areaControl.style.fontSize = '12px';

			areaControl.innerHTML = `
				<div style="font-weight: bold; margin-bottom: 6px;">${area.name}</div>
				<div style="display: flex; gap: 8px; margin-bottom: 4px;">
					<label style="flex: 1; font-size: 11px;">
						W: <span id="width-val-${index}">${area.width}</span>
						<input type="range" id="width-${index}" min="20" max="300" value="${area.width}" step="5" style="width: 100%;">
					</label>
					<label style="flex: 1; font-size: 11px;">
						L: <span id="length-val-${index}">${area.length}</span>
						<input type="range" id="length-${index}" min="20" max="200" value="${area.length}" step="5" style="width: 100%;">
					</label>
				</div>
				<div style="font-size: 11px; color: #aaa;">면적: <span id="area-${index}">${(area.width * area.length).toFixed(0)}</span> m²</div>
			`;

			container.appendChild(areaControl);

			const widthInput = areaControl.querySelector(`#width-${index}`) as HTMLInputElement;
			const lengthInput = areaControl.querySelector(`#length-${index}`) as HTMLInputElement;
			const widthVal = areaControl.querySelector(`#width-val-${index}`) as HTMLElement;
			const lengthVal = areaControl.querySelector(`#length-val-${index}`) as HTMLElement;
			const areaVal = areaControl.querySelector(`#area-${index}`) as HTMLElement;

			widthInput.addEventListener('input', () => {
				this.areasData[index].width = parseFloat(widthInput.value);
				widthVal.textContent = widthInput.value;
				areaVal.textContent = (this.areasData[index].width * this.areasData[index].length).toFixed(0);
				if (this.receptionPoint && this.loadingPoint) this.updateLayout();
			});

			lengthInput.addEventListener('input', () => {
				this.areasData[index].length = parseFloat(lengthInput.value);
				lengthVal.textContent = lengthInput.value;
				areaVal.textContent = (this.areasData[index].width * this.areasData[index].length).toFixed(0);
				if (this.receptionPoint && this.loadingPoint) this.updateLayout();
			});
		});
	}

	private updateCanvasSize() {
		this.canvas.width = this.totalCanvasWidth;
		this.canvas.height = this.totalCanvasHeight;
	}

	private updateLayout() {
		if (!this.receptionPoint || !this.loadingPoint) return;

		const layout = new TreemapLayout(this.canvas.width, this.canvas.height, this.areasData, this.receptionPoint, this.loadingPoint);
		this.placedAreas = layout.calculate();
		this.isStatic = false;
	}

	public render(ctx: CanvasRenderingContext2D): void {
		ctx.fillStyle = '#555';
		ctx.fillRect(0, 0, this.canvas.width, this.canvas.height);

		// 배치된 영역들 그리기
		this.placedAreas.forEach((area) => {
			ctx.fillStyle = area.color;
			ctx.fillRect(area.x, area.y, area.width, area.height);

			ctx.strokeStyle = area.isFixed ? '#FFD700' : 'white';
			ctx.lineWidth = area.isFixed ? 3 : 1.5;
			ctx.strokeRect(area.x, area.y, area.width, area.height);

			ctx.fillStyle = 'white';
			ctx.font = area.isFixed ? 'bold 13px Arial' : 'bold 11px Arial';
			ctx.textAlign = 'left';
			ctx.textBaseline = 'top';

			const padding = 6;
			if (area.width > 40 && area.height > 25) {
				ctx.fillText(area.name, area.x + padding, area.y + padding);

				if (area.isFixed) {
					ctx.font = '9px Arial';
					ctx.fillText('(Fixed)', area.x + padding, area.y + padding + 16);
				}
			}
		});

		if (this.receptionPoint) {
			ctx.fillStyle = '#aa44aa';
			ctx.beginPath();
			ctx.arc(this.receptionPoint.x, this.receptionPoint.y, 6, 0, Math.PI * 2);
			ctx.fill();
			ctx.strokeStyle = 'white';
			ctx.lineWidth = 2;
			ctx.stroke();
		}

		if (this.loadingPoint) {
			ctx.fillStyle = '#FFD700';
			ctx.beginPath();
			ctx.arc(this.loadingPoint.x, this.loadingPoint.y, 6, 0, Math.PI * 2);
			ctx.fill();
			ctx.strokeStyle = 'white';
			ctx.lineWidth = 2;
			ctx.stroke();
		}

		this.isStatic = false;
	}
}
